			select group_concat(interfaces.name, ',') name,
				interfaces.host_id host_id,
				group_concat(interfaces.mac_address, ',') mac_address,
				vlan_interface_assignments.vlan_id vlan_id,
				max(connection_check.connected) connected
			from interfaces
				inner join vlan_interface_assignments
					on interfaces.id = vlan_interface_assignments.interface_id
				left outer join (
					select interfaces.host_id host_id,
						interfaces.number number,
						max(case when interface_links.source_interface_id is null then 0 else 1 end) connected
					from interfaces
						left outer join interface_links
							on interfaces.id = interface_links.source_interface_id
					group by host_id,
						number) connection_check
					on interfaces.host_id = connection_check.host_id
					and interfaces.number = connection_check.number
			group by interfaces.host_id,
				vlan_interface_assignments.vlan_id;
