		if err != nil {
			log.Error(err)
			continue
		}
		if prune != nil {
			delete(*prune, ep.id)
		}
		ep.SetIndex(epe.LastIndex)
		if nid, err := ep.networkIDFromKey(epe.Key); err != nil {
			log.Error(err)
			continue
