		if nid, err := ep.networkIDFromKey(epe.Key); err != nil {
			log.Error(err)
			continue
		} else {
			if n, err := c.NetworkByID(nid); err != nil {
				log.Error(err)
				continue
			} else {
				ep.network = n.(*network)
			}
		}
		if c.processEndpointUpdate(&ep) {
			err = c.newEndpointFromStore(epe.Key, &ep)
			if err != nil {
				log.Error(err)
			}
		}
	}
}

