func isInitializedUnsynced(path string) bool {
	// Check if the config file exists.
	configFilename := filepath.Join(path, config.DefaultConfigFile)
	if _, err := os.Stat(configFilename); err == nil {
		return true
	}
	// Also check for the version file, as a secondary indicator.
	versionFilename := filepath.Join(path, "version")
	if _, err := os.Stat(versionFilename); err == nil {
		return true
	}
	return false
}

