func (g *AlbGenerator) loadLBListenerRules(svc *elasticloadbalancingv2.Client, listenerArn *string) error {
	p := elasticloadbalancingv2.NewDescribeRulesPaginator(svc, &elasticloadbalancingv2.DescribeRulesInput{ListenerArn: listenerArn})
	for p.HasMorePages() {
		page, err := p.NextPage(context.TODO())
		if err != nil {
			return err
		}
		for _, rule := range page.Rules {
			if *rule.IsDefault {
				continue
			}
			resourceName := *rule.RuleArn
			g.Resources = append(g.Resources, terraformutils.NewSimpleResource(
				resourceName,
				resourceName,
				"aws_lb_listener_rule",
				"aws",
				AlbAllowEmptyValues,
			))
		}
	}
	return nil
}

