// get config file path
func configFile(dbname string) string {
	if len(dbname) == 0 {
		return DBCONFIG_FILE
	}
	path := filepath.Join(DATABASE_DIR, faygo.CONFIG_DIR)
	err := os.MkdirAll(path, os.ModePerm)
	if err != nil {
		faygo.Panicf("[sqlx]%v", err)
	}
	return filepath.Join(path, dbname+".ini")
}

// LoadConfig loads the database configuration from the specified ini file.
// If dbname is empty, it loads the default configuration file.
