	db *dnsDB
}

func (s *dbServer) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	switch r.URL.Path {
	case "/":
		s.handleRoot(w, r)
	case "/download":
		s.handleDownload(w, r)
	case "/rotate":
		s.handleRotate(w, r)
	case "/stats":
		s.handleStats(w, r)
	default:
		http.NotFound(w, r)
	}
}

