				if e.URL != tc.expectedURL {
					t.Errorf("Test %d - wrong URL, expected %v, got %v", i, tc.expectedURL, e.URL)
				}
			}
			if !found {
				t.Errorf("Test %d - failed, could not find name %v", i, tc.expectedName)
			}
		}()
	}
}

