		target       string
		pathScope    string
		url          string
		expectedName string
		expectedURL  string
	}{
		// test case can expect a directory "dir" and a symlink to it called "symlink"

		{"dir", "$TMP/rel_symlink_to_dir", "/", "/",
			"rel_symlink_to_dir", "./rel_symlink_to_dir/"},
