 **********************/
func checkPoints(got, want []*dlit.Literal) error {
	if len(got) != len(want) {
		return fmt.Errorf("len(got): %d != len(want): %d, got: %v",
			len(got), len(want), got)
	}
	for i, p := range got {
		if want[i].String() != p.String() {
			return fmt.Errorf("got: %v, want: %v", got, want)
		}
	}
	return nil
}

