	}
}

func runCommandBridge(cmd Command) func(*cli.Context, []string) error {
	return func(ctx *cli.Context, args []string) error {
		// Build command line arguments for the oss command
		var cmdArgs []string
		cmdArgs = append(cmdArgs, cmd.Name)
		cmdArgs = append(cmdArgs, args...)

		// Add flags
		for _, flag := range cmd.Flags {
			if flag.Value != nil && flag.Value.String() != "" {
				cmdArgs = append(cmdArgs, fmt.Sprintf("--%s", flag.Name))
				cmdArgs = append(cmdArgs, flag.Value.String())
			}
