func NewCommandBridge(cmd Command) *cli.Command {
	return &cli.Command{
		Name:   cmd.Name,
		Usage:  cmd.Usage,
		Short:  i18n.T(cmd.ShortEN, cmd.ShortCN),
		Long:   i18n.T(cmd.LongEN, cmd.LongCN),
		Hidden: cmd.Hidden,
		Run: func(c *cli.Context, args []string) error {
			return runCommand(cmd, args)
		},
	}
}

func runCommand(cmd Command, args []string) error {
	// Build command line arguments for the OSS CLI tool
	ossArgs := []string{cmd.Name}
	ossArgs = append(ossArgs, args...)

	// Execute the OSS CLI command
	ossCmd := exec.Command("ossutil", ossArgs...)
	ossCmd.Stdout = os.Stdout
	ossCmd.Stderr = os.Stderr
	ossCmd.Stdin = os.Stdin

	if err := ossCmd.Run(); err != nil {
		return fmt.Errorf("failed to execute ossutil command: %w", err)
	}
	return nil
}

