func (c *Controller) watchClusters() {
	// Use a restartable watcher
	rw, err := k8sutil.NewRestartableWatcher(c.Config.Namespace, c.Config.CRDResource, c.Config.KubeCli, fields.Everything())
	if err != nil {
		panic(err)
	}

	go func() {
		for {
			ev, err := rw.Next()
			if err != nil {
				c.logger.Errorf("watcher error: %v", err)
				time.Sleep(time.Second)
				continue
			}

			cluster := ev.Object.(*api.EtcdCluster)
			cluster = cluster.DeepCopy()

			switch ev.Type {
			case kwatch.Added:
				c.handleClusterEvent(cluster)
			case kwatch.Modified:
				c.handleClusterEvent(cluster)
			case kwatch.Deleted:
				c.handleClusterEvent(cluster)
			}
		}
	}()
}

