func (c *Controller) run() {
	defer c.queue.ShutDown()

	c.logger.Info("starting etcd-operator")

	// Start a goroutine to process events from the queue.
	go c.runWorker()

	// Start the informer which will push events onto the queue.
	go c.runInformer()

	// Wait until we're told to stop.
	<-c.stopCh
	c.logger.Info("stopping etcd-operator")
}

